    """Count the two orientations of four-cell T motifs and encode counts."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (x + dx, y + dy)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            if len(comp) != 4:
                continue
            rows = {}
            for x, y in comp:
                rows.setdefault(x, []).append(y)
            bar = [x for x, ys in rows.items() if len(ys) == 3]
            stem = [x for x, ys in rows.items() if len(ys) == 1]
            if len(bar) == 1 and len(stem) == 1:
                br, sr = bar[0], stem[0]
                bar_cols = sorted(rows[br])
                stem_col = rows[sr][0]
                if len(bar_cols) == 3 and bar_cols[1] == stem_col and abs(br - sr) == 1:
                    counts["up" if sr < br else "down"] += 1

    out = [[0] * 6 for _ in range(3)]
    for color, n, left in ((3, counts["up"], 0), (1, counts["down"], 3)):
        slots = ((0, left), (2, left), (0, left + 2), (2, left + 2))
        for r, c in slots[:n]:
            out[r][c] = color
    return out
